#!/usr/bin/env bats
#
# test_scripts.bats - Test suite for defensive bash scripts
#
# Run with: bats test/test_scripts.bats

setup() {
    # Create temporary test directory
    TEST_DIR="$(mktemp -d)"
    SOURCE_DIR="${TEST_DIR}/source"
    BACKUP_DIR="${TEST_DIR}/backup"

    mkdir -p "${SOURCE_DIR}"
    mkdir -p "${BACKUP_DIR}"

    # Create some test files
    echo "test content 1" > "${SOURCE_DIR}/file1.txt"
    echo "test content 2" > "${SOURCE_DIR}/file2.txt"
    mkdir -p "${SOURCE_DIR}/subdir"
    echo "test content 3" > "${SOURCE_DIR}/subdir/file3.txt"
}

teardown() {
    # Cleanup temporary directory
    if [[ -n "${TEST_DIR}" ]] && [[ -d "${TEST_DIR}" ]]; then
        rm -rf "${TEST_DIR}"
    fi
}

@test "common_utils.sh can be sourced without errors" {
    # shellcheck source=test/common_utils.sh
    run bash -c "source test/common_utils.sh && echo 'sourced'"
    [ "$status" -eq 0 ]
    [[ "${output}" == "sourced" ]]
}

@test "common_utils.sh: log_info outputs to stderr" {
    run bash -c "source test/common_utils.sh && log_info 'test message' 2>&1"
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "[INFO] test message" ]]
}

@test "common_utils.sh: log_error outputs to stderr" {
    run bash -c "source test/common_utils.sh && log_error 'error message' 2>&1"
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "[ERROR] error message" ]]
}

@test "common_utils.sh: die exits with correct code" {
    run bash -c "source test/common_utils.sh && die 'fatal error' 42"
    [ "$status" -eq 42 ]
    [[ "${output}" =~ "[ERROR] fatal error" ]]
}

@test "common_utils.sh: validate_directory fails on non-existent directory" {
    run bash -c "source test/common_utils.sh && validate_directory '/nonexistent/path'"
    [ "$status" -eq 3 ]
}

@test "common_utils.sh: validate_directory succeeds on existing directory" {
    run bash -c "source test/common_utils.sh && validate_directory '${TEST_DIR}'"
    [ "$status" -eq 0 ]
}

@test "common_utils.sh: safe_mkdir creates directory" {
    local new_dir="${TEST_DIR}/new_directory"
    run bash -c "source test/common_utils.sh && safe_mkdir '${new_dir}' && [[ -d '${new_dir}' ]]"
    [ "$status" -eq 0 ]
}

@test "safe_backup.sh: shows usage with -h flag" {
    run test/safe_backup.sh -h
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "Usage:" ]]
}

@test "safe_backup.sh: fails with no arguments" {
    run test/safe_backup.sh
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh: fails with only one argument" {
    run test/safe_backup.sh "${SOURCE_DIR}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh: creates backup successfully" {
    run test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that backup was created
    local backup_count
    backup_count="$(find "${BACKUP_DIR}" -maxdepth 1 -name "backup_*" -type d | wc -l)"
    [ "${backup_count}" -eq 1 ]
}

@test "safe_backup.sh: creates compressed backup with -c flag" {
    run test/safe_backup.sh -c "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that compressed backup was created
    local backup_count
    backup_count="$(find "${BACKUP_DIR}" -maxdepth 1 -name "backup_*.tar.gz" -type f | wc -l)"
    [ "${backup_count}" -eq 1 ]
}

@test "safe_backup.sh: respects retention policy with -r flag" {
    # Create multiple backups
    test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}" >/dev/null 2>&1
    sleep 1
    test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}" >/dev/null 2>&1
    sleep 1
    test/safe_backup.sh "${SOURCE_DIR}" "${BACKUP_DIR}" >/dev/null 2>&1
    sleep 1

    # Apply retention policy to keep only 2
    run test/safe_backup.sh -r 2 "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that only 2 backups remain
    local backup_count
    backup_count="$(find "${BACKUP_DIR}" -maxdepth 1 -name "backup_*" -type d | wc -l)"
    [ "${backup_count}" -eq 2 ]
}

@test "safe_backup.sh: fails on non-existent source directory" {
    run test/safe_backup.sh "/nonexistent/source" "${BACKUP_DIR}"
    [ "$status" -eq 3 ]
}

@test "safe_backup.sh: invalid retention count fails" {
    run test/safe_backup.sh -r "not_a_number" "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh: invalid retention count (zero) fails" {
    run test/safe_backup.sh -r 0 "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh: verbose flag works" {
    run test/safe_backup.sh -v "${SOURCE_DIR}" "${BACKUP_DIR}"
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "[INFO]" ]]
}

